"""MIDI Agent-style WORKFLOW FOUNDATION: bounded prompt -> editable MIDI.

This intentionally implements an original, deterministic music-theory
generator rather than claiming LLM intelligence or copying third-party
source, branding, prompts or weights. Pluggable verified AI providers
are a separate milestone. Every requested part is a distinct SMF track.
"""
from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from hashlib import sha256
from math import ceil, isfinite
import random
import re

import pretty_midi

MAJOR = (0, 2, 4, 5, 7, 9, 11)
MINOR = (0, 2, 3, 5, 7, 8, 10)
NOTE_PC = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
PARTS = ("chords", "melody", "bass", "drums")
KEY_RE = re.compile(
    r"(?<![A-Za-z])([A-Ga-g])([#b♯♭]?)[\s-]*(major|minor|maj|min)(?![A-Za-z])",
    re.I,
)
BARS_RE = re.compile(r"(?<!\d)(\d{1,2})\s*(?:bars?|measures?|小節)(?![A-Za-z])", re.I)
BPM_RE = re.compile(r"(?<!\d)(\d{2,3})\s*(?:bpm|拍/分)(?![A-Za-z])", re.I)


@dataclass(frozen=True)
class PromptSpec:
    prompt: str
    key: str
    mode: str
    bars: int
    bpm: float
    parts: tuple[str, ...]
    seed: int
    sparse: bool
    syncopated: bool
    rising: bool

    def __post_init__(self):
        if not 1 <= self.bars <= 32 or not 40 <= self.bpm <= 240:
            raise ValueError("bars must be 1..32 and BPM must be 40..240")
        if self.mode not in ("major", "minor") or self.key not in NOTE_PC and not (
            len(self.key) == 2 and self.key[0] in NOTE_PC and self.key[1] in "#b"
        ):
            raise ValueError("Invalid major/minor key")
        if not self.parts or any(p not in PARTS for p in self.parts):
            raise ValueError("No supported MIDI parts")
        if type(self.seed) is not int or not 0 <= self.seed < 2**32:
            raise ValueError("seed must be a 32-bit unsigned integer")


def parse_prompt(
    prompt: str, *, key: str | None = None,
    mode: str | None = None, bars: int | None = None,
    bpm: float | None = None, parts: tuple[str, ...] | None = None,
    seed: int | None = None,
) -> PromptSpec:
    if not isinstance(prompt, str) or not 1 <= len(prompt.strip()) <= 1500:
        raise ValueError("Prompt must contain 1..1500 characters")
    p = prompt.strip()
    lower = p.casefold()
    found = KEY_RE.search(p)
    chinese = re.search(r"([A-Ga-g])([#b♯♭]?)(大調|小調)", p)
    key_name = key if key is not None else (
        (found.group(1) + found.group(2)) if found
        else chinese.group(1) + chinese.group(2) if chinese else "C"
    )
    key_name = key_name[:1].upper() + key_name[1:].replace("♯", "#").replace("♭", "b")
    if mode is None:
        mode = ("minor" if (found and found.group(3).lower() in ("minor", "min"))
                else "minor" if chinese and chinese.group(3) == "小調"
                else "major")
    mode = mode.lower()
    if bars is None:
        bar_match = BARS_RE.search(p)
        bars = int(bar_match.group(1)) if bar_match else 4
    if bpm is None:
        tempo_match = BPM_RE.search(p)
        bpm = float(tempo_match.group(1)) if tempo_match else 120.0
    if parts is None:
        requested = []
        identifiers = {
            "chords": ("chord", "harmony", "harmonies", "和弦", "和聲"),
            "melody": ("melody", "lead", "hook", "旋律", "主旋律"),
            "bass": ("bass", "bassline", "貝斯", "低音"),
            "drums": ("drum", "beat", "percussion", "鼓", "打擊"),
        }
        # Whole song/arrangement explicitly asks for a full four-part sketch.
        full = any(token in lower for token in (
            "whole song", "full song", "full arrangement", "all parts",
            "全曲", "完整編曲", "全部聲部", "整首"
        ))
        for role, keywords in identifiers.items():
            if full or any(word in lower for word in keywords):
                requested.append(role)
        parts = tuple(requested) or PARTS
    if seed is None:
        seed = int.from_bytes(sha256(p.encode("utf-8")).digest()[:4], "big")
    return PromptSpec(
        prompt=p, key=key_name, mode=mode, bars=bars,
        bpm=float(bpm), parts=tuple(parts), seed=seed,
        sparse=any(x in lower for x in ("sparse", "minimal", "spacious", "簡約", "稀疏")),
        syncopated=any(x in lower for x in ("syncopat", "funk", "house", "swing", "切分", "律動")),
        rising=any(x in lower for x in ("rising", "climb", "build tension", "上行", "漸強")),
    )


def _tonic(spec: PromptSpec) -> int:
    root = NOTE_PC[spec.key[0]]
    accidental = (1 if spec.key.endswith("#") else -1 if spec.key.endswith("b") else 0)
    return (root + accidental) % 12


def _notes_for_chord(root_pc: int, scale: tuple[int, ...], degree: int) -> list[int]:
    # Diatonic thirds stacked from scale degrees, with octave wrapping.
    indexes = (degree, degree + 2, degree + 4)
    return [
        48 + root_pc + scale[j % 7] + (12 if j >= 7 else 0)
        for j in indexes
    ]


def generate_sketch(
    spec: PromptSpec, *, source: pretty_midi.PrettyMIDI | None = None,
) -> pretty_midi.PrettyMIDI:
    """Return separately editable chord/melody/bass/drum tracks.

    Existing source MIDI is deep-copied unchanged. Extension uses a constant
    tempo, 4/4 bar-aligned tail; complex source tempo/meter fails closed.
    """
    if not isinstance(spec, PromptSpec):
        raise ValueError("Expected validated PromptSpec")
    if source is not None:
        if not isinstance(source, pretty_midi.PrettyMIDI):
            raise ValueError("Source must be Standard MIDI")
        if any((x.numerator, x.denominator) != (4, 4)
               for x in source.time_signature_changes):
            raise ValueError("Extension currently supports 4/4 only")
        _, tempos = source.get_tempo_changes()
        if len(tempos) != 1:
            raise ValueError("Extension requires constant source tempo")
        if abs(float(tempos[0]) - spec.bpm) > 0.02:
            raise ValueError("Extension BPM must equal source MIDI tempo")
        result = deepcopy(source)
    else:
        result = pretty_midi.PrettyMIDI(initial_tempo=spec.bpm)
    sec_beat = 60.0 / spec.bpm
    sec_bar = 4.0 * sec_beat
    start_bar = (ceil((result.get_end_time() - 1e-7) / sec_bar)
                 if source is not None else 0)
    start_seconds = max(0, start_bar) * sec_bar
    tonic = _tonic(spec)
    scale = MINOR if spec.mode == "minor" else MAJOR
    roots = (0, 5, 2, 6) if spec.mode == "minor" else (0, 5, 3, 4)
    rng = random.Random(spec.seed)

    tracks = {
        "chords": pretty_midi.Instrument(program=0, name="MIDIVOLT | Chords"),
        "melody": pretty_midi.Instrument(program=80, name="MIDIVOLT | Melody"),
        "bass": pretty_midi.Instrument(program=33, name="MIDIVOLT | Bass"),
        "drums": pretty_midi.Instrument(program=0, is_drum=True, name="MIDIVOLT | Drums"),
    }

    def add(role: str, pitch: int, bar: int, beat: float, length: float, velocity: int):
        begin = start_seconds + (bar * 4 + beat) * sec_beat
        end = begin + length * sec_beat
        max_end = start_seconds + spec.bars * sec_bar
        if pitch < 0 or pitch > 127 or end > max_end + 1e-8 or end <= begin:
            raise ValueError("Invalid generated note pitch/duration")
        tracks[role].notes.append(pretty_midi.Note(
            velocity=velocity, pitch=pitch, start=begin, end=min(end, max_end)
        ))

    for bar in range(spec.bars):
        degree = roots[bar % 4]
        chord = _notes_for_chord(tonic, scale, degree)
        # Chords: triads, four beats long, no opaque generated audio.
        if "chords" in spec.parts:
            for pitch in chord:
                add("chords", pitch, bar, 0, 3.8, 70)
        if "bass" in spec.parts:
            pitch = 36 + (tonic + scale[degree]) % 12
            beats = (0, 2.5) if spec.syncopated else (0, 2)
            for beat in beats:
                add("bass", pitch, bar, beat, .75 if spec.syncopated else 1.75, 80)
        if "melody" in spec.parts:
            beats = (0.0, 2.0) if spec.sparse else (0.0, 1.0, 2.0, 3.0)
            for i, beat in enumerate(beats):
                # Generated melody stays in-key and references local harmony.
                step = ((bar + i) % 7) if spec.rising else rng.choice((degree, degree+2, degree+4)) % 7
                pitch = 60 + (tonic + scale[step]) % 12
                add("melody", pitch, bar, beat, .7 if not spec.sparse else 1.55,
                    70 + rng.randint(-8, 8))
        if "drums" in spec.parts:
            # Standard General MIDI drum note numbers.
            for beat in (0, 2):
                add("drums", 36, bar, beat, .16, 105)
            for beat in ((2,) if "half-time" in spec.prompt.lower() else (1, 3)):
                add("drums", 38, bar, beat, .13, 93)
            for h in range(8):
                add("drums", 42, bar, h * .5, .11,
                    69 if h % 2 else 78)
    for role in PARTS:
        if role in spec.parts:
            if not tracks[role].notes:
                raise ValueError("Requested part has no generated notes")
            result.instruments.append(tracks[role])
    return result


def report(spec: PromptSpec, midi: pretty_midi.PrettyMIDI, *, extended: bool) -> dict:
    return {
        "engine": "original_deterministic_music_theory_generator_v1",
        "llm_inference_used": False, "pretrained_weights_bundled": False,
        "original_midi_preserved": bool(extended),
        "key": spec.key, "mode": spec.mode, "bars_generated": spec.bars,
        "bpm": spec.bpm, "seed": spec.seed, "parts": list(spec.parts),
        "tracks_total": len(midi.instruments),
        "notes_total": sum(len(i.notes) for i in midi.instruments),
        "DAW_plugin_integration": False,
    }

"""Reviewable, non-destructive MIDI arrangement proposals.

Supports any candidate MIDI generator, including external AI models. An
explicit lock list protects original tracks; global timing maps are locked.
No LLM or network client is bundled in this module.
"""
from __future__ import annotations

from collections import Counter
from hashlib import sha256
from io import BytesIO
import json
import os
from pathlib import Path
import tempfile

import pretty_midi

from ._approval_snapshot import read_approved_snapshots
from .io import read_midi, write_midi

SCHEMA_VERSION = 1


def _digest(path: Path) -> str:
    with path.open("rb") as file:
        h = sha256()
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            h.update(chunk)
        return h.hexdigest()


def _event_time(reference: pretty_midi.PrettyMIDI, seconds: float) -> int:
    return int(reference.time_to_tick(seconds))


def _note_events(reference: pretty_midi.PrettyMIDI, instrument) -> Counter:
    return Counter((
        int(n.pitch), int(n.velocity),
        _event_time(reference, n.start),
        _event_time(reference, n.end),
    ) for n in instrument.notes)


def _automation_events(reference: pretty_midi.PrettyMIDI, instrument) -> tuple:
    cc = Counter((
        int(c.number), int(c.value), _event_time(reference, c.time)
    ) for c in instrument.control_changes)
    bend = Counter((
        int(b.pitch), _event_time(reference, b.time)
    ) for b in instrument.pitch_bends)
    return cc, bend


def _global_signature(midi: pretty_midi.PrettyMIDI) -> tuple:
    times, bpms = midi.get_tempo_changes()
    tempo = tuple((round(float(t), 6), round(float(bpm), 4))
                  for t, bpm in zip(times, bpms))
    meter = tuple((int(m.numerator), int(m.denominator),
                   round(float(m.time), 6))
                  for m in midi.time_signature_changes)
    key = tuple((int(k.key_number), round(float(k.time), 6))
                for k in midi.key_signature_changes)
    return tempo, meter, key


def inspect_arrangement(
    source: pretty_midi.PrettyMIDI,
    candidate: pretty_midi.PrettyMIDI,
    locked_tracks: list[int],
) -> dict:
    """Validate source/candidate and return note-level diff by track index.

    Track indexes intentionally remain significant. Rearranging instrument
    order changes the diff and cannot bypass a locked source track.
    """
    if _global_signature(source) != _global_signature(candidate):
        raise ValueError("Candidate changes tempo, meter or key map; global timing is locked.")
    if not locked_tracks or len(set(locked_tracks)) != len(locked_tracks):
        raise ValueError("Provide unique locked track indices (at least one).")
    if any(type(i) is not int or i < 0 or i >= len(source.instruments)
           for i in locked_tracks):
        raise ValueError("Locked track index is out of source MIDI range.")

    changes: list[dict] = []
    for idx in range(max(len(source.instruments), len(candidate.instruments))):
        before = source.instruments[idx] if idx < len(source.instruments) else None
        after = candidate.instruments[idx] if idx < len(candidate.instruments) else None
        old_notes = _note_events(source, before) if before else Counter()
        new_notes = _note_events(source, after) if after else Counter()
        removed = sum((old_notes - new_notes).values())
        added = sum((new_notes - old_notes).values())

        if idx in locked_tracks:
            if after is None or before is None:
                raise ValueError(f"Locked track {idx} was removed.")
            if (before.name, before.program, before.is_drum) != (
                after.name, after.program, after.is_drum
            ):
                raise ValueError(f"Locked track {idx} identity/instrument changed.")
            if old_notes != new_notes or (
                _automation_events(source, before) !=
                _automation_events(source, after)
            ):
                raise ValueError(f"Locked track {idx} MIDI events changed.")

        metadata_changed = bool(before and after and (
            (before.name, before.program, before.is_drum) !=
            (after.name, after.program, after.is_drum) or
            _automation_events(source, before) !=
            _automation_events(source, after)
        ))
        if added or removed or before is None or after is None or metadata_changed:
            changes.append({
                "track": idx,
                "before": before.name if before else None,
                "after": after.name if after else None,
                "notes_added": added,
                "notes_removed": removed,
                "metadata_or_automation_changed": metadata_changed,
                "locked": idx in locked_tracks,
            })
    return {
        "original_tracks": len(source.instruments),
        "candidate_tracks": len(candidate.instruments),
        "locked_tracks": list(locked_tracks),
        "notes_added": sum(t["notes_added"] for t in changes),
        "notes_removed": sum(t["notes_removed"] for t in changes),
        "tracks_changed": changes,
    }


def _distinct_paths(*paths: Path) -> None:
    resolved = [p.resolve() for p in paths]
    if len(set(resolved)) != len(resolved):
        raise ValueError("Input, candidate, manifest and output must be separate paths.")


def _save_new_json(path: Path, payload: dict) -> None:
    """Stage JSON then publish without truncating any existing manifest."""
    if path.suffix.lower() != ".json":
        raise ValueError("Proposal manifest must end with .json.")
    if not path.parent.is_dir():
        raise FileNotFoundError(f"Manifest directory missing: {path.parent}")
    if path.exists():
        raise FileExistsError(path)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    os.close(fd)
    try:
        Path(tmp).write_text(
            json.dumps(payload, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
        os.link(tmp, path)
    finally:
        Path(tmp).unlink(missing_ok=True)


def create_proposal(
    input_path: str | Path, candidate_path: str | Path,
    manifest_path: str | Path, *, locked_tracks: list[int],
) -> dict:
    original = Path(input_path).resolve()
    candidate = Path(candidate_path).resolve()
    manifest = Path(manifest_path).resolve()
    _distinct_paths(original, candidate, manifest)
    review = inspect_arrangement(
        read_midi(original), read_midi(candidate), locked_tracks
    )
    proposal = {
        "schema_version": SCHEMA_VERSION,
        "source": str(original),
        "candidate": str(candidate),
        "source_sha256": _digest(original),
        "candidate_sha256": _digest(candidate),
        "locked_tracks": list(locked_tracks),
        "review": review,
    }
    _save_new_json(manifest, proposal)
    return proposal


def check_proposal(manifest_path: str | Path) -> tuple[dict, dict]:
    manifest = Path(manifest_path).resolve()
    try:
        data = json.loads(manifest.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid proposal JSON.") from exc
    if not isinstance(data, dict) or data.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("Unsupported proposal schema.")
    src, can = Path(data["source"]).resolve(), Path(data["candidate"]).resolve()
    _distinct_paths(src, can, manifest)
    if (_digest(src) != data["source_sha256"] or
            _digest(can) != data["candidate_sha256"]):
        raise ValueError("Source/candidate changed since proposal; create a new proposal.")
    report = inspect_arrangement(read_midi(src), read_midi(can), data["locked_tracks"])
    if report != data["review"]:
        raise ValueError("Proposal review mismatch; create a new proposal.")
    return data, report


def apply_proposal(
    manifest_path: str | Path, output_path: str | Path,
    *, approved: bool,
) -> dict:
    if not approved:
        raise PermissionError("Arrangement must be explicitly approved with --approve.")
    manifest = Path(manifest_path).resolve()
    data, report = check_proposal(manifest)
    dest = Path(output_path).resolve()
    _distinct_paths(
        Path(data["source"]), Path(data["candidate"]), manifest, dest,
    )
    # Never overwrite an existing project, and revalidate immediately prior to publish.
    if dest.exists():
        raise FileExistsError(f"Output already exists: {dest}")
    # check_proposal validates disk files, but they can change before a
    # second read. Freeze the exact approved bytes and serialize ONLY those.
    source_bytes, candidate_bytes = read_approved_snapshots(
        Path(data["source"]), Path(data["candidate"]),
        data["source_sha256"], data["candidate_sha256"],
    )
    reviewed_source = pretty_midi.PrettyMIDI(BytesIO(source_bytes))
    reviewed_candidate = pretty_midi.PrettyMIDI(BytesIO(candidate_bytes))
    if inspect_arrangement(reviewed_source, reviewed_candidate, data["locked_tracks"]) != report:
        raise ValueError("Approved MIDI snapshot differs from the reviewed proposal.")
    write_midi(reviewed_candidate, dest)
    return {**report, "output": str(dest), "approved": True}

"""MIDIVOLT external tsov MCP CLI: read-only by default."""
from __future__ import annotations

import argparse
import json
import math
import sys
from pathlib import Path

from .tsov_mcp import McpStdioSession, TsovMcpError, tsov_command, validate_project


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="midivolt-tsov",
        description="Call separately installed tsov MCP. Writes require --apply.",
    )
    p.add_argument("--python", required=True,
                   help="tsov Python 3.12 virtualenv executable")
    p.add_argument("--root", required=True,
                   help="Path to the separately cloned tsov repo")
    p.add_argument("--timeout", type=float, default=60.0)
    sub = p.add_subparsers(dest="command", required=True)
    sub.add_parser("projects", help="List tsov projects")
    sub.add_parser("tools", help="List permitted MCP tools offered by tsov")
    for name in ("status", "history", "undo", "redo"):
        c = sub.add_parser(name)
        c.add_argument("--project", required=True)
        if name == "history":
            c.add_argument("--limit", type=int, default=20)
        if name in ("undo", "redo"):
            c.add_argument("--apply", action="store_true")
    edit = sub.add_parser("edit", help="Apply LLM edit to one selected track")
    edit.add_argument("--project", required=True)
    edit.add_argument("--track", required=True,
                      help="Explicit track name or index")
    edit.add_argument("--feedback", required=True)
    edit.add_argument("--apply", action="store_true")
    tempo = sub.add_parser("tempo", help="Change project BPM")
    tempo.add_argument("--project", required=True)
    tempo.add_argument("--bpm", type=float, required=True)
    tempo.add_argument("--remap", action="store_true",
                       help="Also rescale time; default only changes BPM header")
    tempo.add_argument("--apply", action="store_true")
    return p


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    writing = args.command in {"edit", "tempo", "undo", "redo"}
    try:
        if not math.isfinite(args.timeout) or args.timeout <= 0 or args.timeout > 600:
            raise ValueError("--timeout must be between 0 and 600 seconds.")
        if writing and not args.apply:
            raise PermissionError("Refusing project mutation without --apply.")
        if hasattr(args, "project"):
            validate_project(args.project)
        if args.command == "edit" and (
            not args.feedback.strip() or not args.track.strip()
        ):
            raise ValueError("--feedback and --track must not be empty.")
        if args.command == "tempo" and (
            not math.isfinite(args.bpm) or not 20 <= args.bpm <= 400
        ):
            raise ValueError("--bpm must be finite and between 20 and 400.")
        command = tsov_command(args.python, args.root, allow_write=writing)
        with McpStdioSession(
            command, cwd=Path(args.root).resolve(),
            timeout=args.timeout, allow_write=writing,
        ) as session:
            if args.command == "projects":
                result = session.call("list_projects")
            elif args.command == "tools":
                result = {"tools": list(session.available_tools)}
            elif args.command == "status":
                result = session.call("project_status",
                                      {"project": args.project})
            elif args.command == "history":
                if not 1 <= args.limit <= 100:
                    raise ValueError("--limit must be 1..100.")
                result = session.call(
                    "list_history", {"project": args.project, "limit": args.limit})
            elif args.command == "edit":
                track = int(args.track) if (
                    args.track.isascii() and args.track.isdecimal()
                ) else args.track
                result = session.call("edit_score", {
                    "project": args.project, "track": track,
                    "feedback": args.feedback,
                })
            elif args.command == "tempo":
                result = session.call("set_tempo", {
                    "project": args.project, "tempo": args.bpm,
                    "remap": args.remap,
                })
            else:
                result = session.call(
                    args.command, {"project": args.project})
            print(json.dumps(result, ensure_ascii=False, indent=2))
            return 0
    except (ValueError, PermissionError, FileNotFoundError,
            OSError, TsovMcpError) as exc:
        print(f"MIDIVOLT tsov MCP: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
